    array('name' => 'John', 'address' => 'New York', 'age' => 35),
    array('name' => 'Jane', 'address' => 'Boston', 'age' => 27),
    array('name' => 'Mark', 'address' => 'Chicago', 'age' => 32)
);

print_r(smart_sort_array($arr)); // Ascending Order
print_r(smart_sort_array($arr, 'DESC')); // Descending Order
```

