using UnityEngine;
using UnityEngine.UI;

public class Visualizer : MonoBehaviour
{
    public AudioSource audioSource; // Reference to the audio source
    public RectTransform barContainer; // Reference to the container holding all bars
    public float maxAmplitude = 100f; // Maximum amplitude value

    private float[] samples = new float[64]; // Buffer for storing sample data
    private float[] barHeights = new float[64]; // Array to store heights of each bar

    void Start()
    {
        if (audioSource == null)
            Debug.LogError("Please assign an AudioSource to this Visualizer.");

        if (barContainer == null)
            Debug.LogError("Please assign a RectTransform as the bar container.");
    }

    void Update()
    {
        GetSpectrumData();
        UpdateBars();
    }

    void GetSpectrumData()
    {
        audioSource.GetSpectrumData(samples, 0, FFTWindow.Blackman); // Get spectrum data from audio source
    }

    void UpdateBars()
    {
        for (int i = 0; i < samples.Length; i++)
        {
            barHeights[i] = Mathf.Lerp(barHeights[i], samples[i] * maxAmplitude, 0.1f); // Smoothly interpolate bar height based on current sample
            Transform barTransform = barContainer.GetChild(i);
            barTransform.localScale = new Vector3(1, barHeights[i], 1); // Set bar height
        }
    }
}
```

