 To create a simple toast notification using React and the useContext Hook, follow these steps:

First, let's create a custom context for managing the toast messages. Create a new file `ToastContext.js`:

```javascript
import { createContext } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = React.useState([]);

  const addToast = (message) => {
    setToasts((prevToasts) => [...prevToasts, message]);

    // Clear toast messages after some time (optional)
    setTimeout(() => {
      setToasts(prevToasts => prevToasts.filter((_, index) => index !== prevToasts.length - 1));
    }, 3000);
  };

  return (
    <ToastContext.Provider value={{ toasts, addToast }}>
      {children}
    </ToastContext.Provider>
  );
};
```

Now, create a component for displaying the toast notifications called `ToastComponent.js`:

```javascript
import React from 'react';
import { ToastContext } from './ToastContext';

const Toast = () => {
  const { toasts } = React.useContext(ToastContext);

  return (
    <div className="toast-container">
      {toasts.map((msg, i) => (
        <div key={i} className="toast">{msg}</div>
      ))}
    </div>
  );
};

export default Toast;
```

Finally, use the `ToastProvider` in your main `App.js` file and wrap it around your components:

```javascript
import React from 'react';
import { ToastProvider } from './ToastContext';
import Toast from './ToastComponent';
import YourComponent from './YourComponent';

function App() {
  return (
    <ToastProvider>
      <Toast />
      <YourComponent />
    </ToastProvider>
  );
}

export default App;
```

