 I'd be happy to help you write a PowerShell script that recursively checks folders for Access Control Lists (ACLs) with SIDs from the SIDHistory of any user or group in the Active Directory domain. Here's a script that should meet your requirements:

```powershell
# Set your domain and forest FQDN here
$DomainFqdn = "yourdomain.com"
$ForestFqdn = "forest.yourdomain.com"

# Function to get all SIDs from SID History of users and groups in the domain
function Get-SidHistory {
    $Filter = "(objectClass -eq 'user') OR (objectClass -eq 'group)'";
    $Searcher = New-Object -ComObject "ADSISEARCHER"
    $Searcher.Filter = $Filter
    $Searcher.PropertiesToLoad.Add("sIDHistory")

    $Results = @()
    while ($Searcher.FindNext()) {
        $Result = $Searcher.GetDirectoryEntry()
        $Sids = $Result.sIDHistory
        $Results += $Sids
    }

    return [System.String]::Join(",", $Results)
}

# Function to check if a given folder has any access rule using the provided SID
function Check-FolderAcl {
    param(
        [Parameter(Mandatory=$true)]
        [string]$Path,
        [Parameter(Mandatory=$true)]
        [string]$Sid
    )

    $Access = Get-Acl -Path $Path
    $Rules = $Access.Access | Where-Object {$_.IdentityReference.Value -eq $Sid}

    if ($Rules) {
        Write-Host "Found match in '$Path': $_" -NoNewline
        $Rules | ForEach-Object {Write-Host $_.FileSystemAccessRule.AccessControlType.Name}
        Write-Host ""
    }
}

